    sh:message "s223: An `ActuatableProperty` normally is referred to by `Equipment` using the relation `actuatedByProperty`." ;
    sh:minCount 1 ;
    sh:path [ sh:inversePath s223:actuatedByProperty ] ;
    sh:severity sh:Warning .

