http://data.ashrae.org/standard223#Actua.cbd:
@prefix doc: <http://sample.org/doc#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix s223: <http://data.ashrae.org/standard223#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

s223:Actuator a s223:Class,
        sh:NodeShape ;
    rdfs:label "Actuator" ;
    doc:subclauses ( s223:actuates s223:actuatedByProperty ) ;
    rdfs:comment """A piece of `Equipment` that receives control signals and electrically, pneumatically, or hydraulically makes changes in the
physical world, such as the position of a valve or damper.""" ;
    rdfs:subClassOf s223:Equipment ;
    sh:property [ rdfs:comment "An `Actuator` shall be associated with at least one `ActuatableProperty` using the relation `actuatedByProperty`." ;
            sh:class s223:ActuatableProperty ;
            sh:message "s223: An `Actuator` shall be associated with at least one `ActuatableProperty` using the relation `actuatedByProperty`." ;
            sh:minCount 1 ;
            sh:path s223:actuatedByProperty ],
        [ rdfs:comment "An `Actuator` shall be associated with zero or more pieces of `Equipment` using the relation `actuates`." ;
            sh:class s223:Equipment ;
            sh:message "s223: An `Actuator` shall be associated with zero or more pieces of `Equipment` using the relation `actuates`." ;
            sh:path s223:actuates ] .

