@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

s223:Bathtub a s223:Class,
        sh:NodeShape ;
    rdfs:label "Bathtub" ;
    rdfs:comment "A piece of `Equipment` for bathing that receives as an input hot or cold water dispensed from one or two `Faucet`s, and is designed to hold a specific volume of water and release the held water through a `Drain`." ;
    rdfs:subClassOf s223:Equipment ;
    sh:property [ rdfs:comment "A `Bathtub` shall have at least one inlet using the medium `Fluid-Water`." ;
            sh:message "s223: A `Bathtub` shall have at least one inlet using the medium `Fluid-Water`." ;
            sh:path s223:hasConnectionPoint ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:InletConnectionPoint ;
                    sh:node [ sh:property [ sh:class s223:Fluid-Water ;
                                    sh:path s223:hasMedium ] ] ] ],
        [ rdfs:comment "A `Bathtub` shall have at least one outlet using the medium `Fluid-Water`." ;
            sh:message "s223: A `Bathtub` shall have at least one outlet using the medium `Fluid-Water`." ;
            sh:path s223:hasConnectionPoint ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:OutletConnectionPoint ;
                    sh:node [ sh:property [ sh:class s223:Fluid-Water ;
                                    sh:path s223:hasMedium ] ] ] ] .

