s223:ElectricityMeter a s223:Class,
        sh:NodeShape ;
    rdfs:label "Electricity meter" ;
    rdfs:comment """A piece of `Equipment` that contains at least one `VoltageSensor` and one `ElectricCurrentSensor`, and reports one or more
properties of electricity. Example reported properties include the following `QuantityKind`s: `Voltage`, `ElectricCurrent`, `ActiveEnergy`,
`ActivePower`, `ReactivePower`, `ApparentPower`, `PowerFactor`, and `Frequency` with unit Hertz. An `ElectricityMeter` may optionally contain a `Function` that represents the mathematical calculations of the reported properties of electricity.""" ;
    rdfs:subClassOf s223:Equipment ;
    sh:property [ rdfs:comment "An `ElectricityMeter` shall contain at least one `ElectricCurrentSensor`." ;
            sh:message "s223: An `ElectricityMeter` shall contain at least one `ElectricCurrentSensor`." ;
            sh:path s223:contains ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:ElectricCurrentSensor ] ;
            sh:qualifiedValueShapesDisjoint true ],
        [ rdfs:comment "The medium observed by the sensors contained by an `ElectricityMeter` shall be a `Constituent-Electricity`." ;
            sh:class s223:Constituent-Electricity ;
            sh:message "s223: The medium observed by the sensors contained by an `ElectricityMeter` shall be a `Constituent-Electricity`." ;
            sh:minCount 1 ;
            sh:path ( s223:contains s223:hasObservationLocation s223:hasMedium ) ],
        [ rdfs:comment "The observation location of the sensors contained by an `ElectricityMeter` shall be either a `Connection` or a `ConnectionPoint`." ;
            sh:message "s223: The observation location of the sensors contained by an `ElectricityMeter` shall be either a `Connection` or a `ConnectionPoint`." ;
            sh:minCount 1 ;
            sh:or ( [ sh:class s223:Connection ] [ sh:class s223:ConnectionPoint ] ) ;
            sh:path ( s223:contains s223:hasObservationLocation ) ],
        [ rdfs:comment "An `ElectricityMeter` shall contain at least one `VoltageSensor`." ;
            sh:message "s223: An `ElectricityMeter` shall contain at least one `VoltageSensor`." ;
            sh:path s223:contains ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:VoltageSensor ] ;
            sh:qualifiedValueShapesDisjoint true ] .

