@prefix ns6: <http://data.ashrae.org/standard223/1.0/validation/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix s223: <http://data.ashrae.org/standard223#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

s223:ElectricityMeterSensorLocationShape a sh:NodeShape ;
    rdfs:comment "An `ElectricityMeter` shall contain a `VoltageSensor` and `ElectricCurrentSensor` with the same observation location." ;
    sh:sparql [ a sh:SPARQLConstraint ;
            rdfs:comment "An `ElectricityMeter` shall contain a `VoltageSensor` and `ElectricCurrentSensor` with the same observation location." ;
            sh:message "s223: {$this} does not contain a `VoltageSensor` and `ElectricCurrentSensor` with a shared observation location." ;
            sh:prefixes ns6:model ;
            sh:select """
SELECT $this
WHERE {
  FILTER NOT EXISTS {
    $this s223:contains ?voltageSensor .
    $this s223:contains ?currentSensor .
    ?voltageSensor a/rdfs:subClassOf* s223:VoltageSensor ;
                   s223:hasObservationLocation ?location .
    ?currentSensor a/rdfs:subClassOf* s223:ElectricCurrentSensor ;
                   s223:hasObservationLocation ?location .
  }
}
""" ] ;
    sh:targetClass s223:ElectricityMeter .

