            sh:maxCount 1 ;
            sh:message "s223: An `EnumerationKind-Numerical` shall be associated with exactly one `QuantityKind` using the relation `qudt:hasQuantityKind`." ;
            sh:minCount 1 ;
            sh:path qudt:hasQuantityKind ],
        [ rdfs:comment "An `EnumerationKind-Numerical` shall be associated with at most one decimal value using the relation `hasValue`." ;
            sh:datatype xsd:decimal ;
            sh:maxCount 1 ;
            sh:message "s223: An `EnumerationKind-Numerical` shall be associated with at most one decimal value using the relation `hasValue`." ;
            sh:path s223:hasValue ] .

