http://data.ashrae.org/standard223#Equip.cbd:
@prefix ns6: <http://data.ashrae.org/standard223/1.0/validation/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix s223: <http://data.ashrae.org/standard223#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

s223:Equipment a s223:Class,
        sh:NodeShape ;
    rdfs:label "Equipment" ;
    rdfs:comment """`Equipment` is the modeling construct used to represent a thing designed to accomplish a specific task, or a complex thing
that contains component pieces of `Equipment` that are connected to each other and work together to accomplish a task. `Equipment` can have
`Connection`s and `ConnectionPoint`s through which one or more kinds of medium (see {s223:Substance-Medium}) might flow. Examples of `Equipment` defined in this ontology include `Pump`, `Fan`, `AirHeatExchanger`, `Luminaire`, and `Sensor`. `Equipment` can be connected to other `Connectable`s such as other `Equipment` or `DomainSpace`s.

The graphical depiction of Equipment used in this document is a round-cornered rectangle as shown in Figure 5-1.

![Graphical Depiction of Equipment.](figures/Figure_5-1_Graphical_Depiciton_of_Equipment.svg)""" ;
    rdfs:subClassOf s223:Connectable ;
    sh:property [ rdfs:comment "A piece of `Equipment` shall be associated with zero or more `PhysicalSpace`s using the relation `hasPhysicalLocation`." ;
            sh:class s223:PhysicalSpace ;
            sh:message "s223: A piece of `Equipment` shall be associated with zero or more `PhysicalSpace`s using the relation `hasPhysicalLocation`." ;
            sh:path s223:hasPhysicalLocation ],
        [ rdfs:comment "A piece of `Equipment` shall be associated with zero or more `EnumerationKind-Role`s using the relation `hasRole`." ;
            sh:class s223:EnumerationKind-Role ;
            sh:message "s223: A piece of `Equipment` shall be associated with zero or more `EnumerationKind-Role`s using the relation `hasRole`." ;
            sh:path s223:hasRole ],
        [ rdfs:comment "Disallow contained equipment from having external incoming connections." ;
            sh:message "s223: Disallow contained equipment from having external incoming connections." ;
            sh:path s223:connectedFrom ;
            sh:sparql [ a sh:SPARQLConstraint ;
                    rdfs:comment "Disallow contained equipment from having external incoming connections." ;
                    sh:message "s223: {$this} should not have a connection from external equipment {?otherDev} because {?container} contains {$this}." ;
                    sh:prefixes ns6:model ;
                    sh:select """
SELECT $this ?container ?otherDev
WHERE {
$this s223:connectedFrom ?otherDev .
$this ^s223:contains ?container .
?container a/rdfs:subClassOf* s223:Equipment .
FILTER NOT EXISTS {?container s223:contains ?otherDev .}
}
""" ] ],
        [ rdfs:comment "A piece of `Equipment` shall be associated with zero or more `ActuatableProperty`s using the relation `actuatedByProperty`." ;
            sh:class s223:ActuatableProperty ;
            sh:message "s223: A piece of `Equipment` shall be associated with zero or more `ActuatableProperty`s using the relation `actuatedByProperty`." ;
            sh:path s223:actuatedByProperty ],
        [ rdfs:comment "A piece of `Equipment` shall be associated with zero or more `Function`s using the relation `executes`." ;
            sh:class s223:Function ;
            sh:message "s223: A piece of `Equipment` shall be associated with zero or more `Function`s using the relation `executes`." ;
            sh:path s223:executes ],
        [ a sh:PropertyShape ;
            rdfs:comment "A piece of `Equipment` shall be associated with zero or more other pieces of contained `Equipment` and/or `Junction`s using the relation `contains`." ;
            sh:message "s223: A piece of `Equipment` shall be associated with zero or more other pieces of contained `Equipment` and/or `Junction`s using the relation `contains`." ;
            sh:name "device contains shape" ;
            sh:or ( [ sh:class s223:Equipment ] [ sh:class s223:Junction ] ) ;
            sh:path s223:contains ],
        [ rdfs:comment "Disallow contained equipment from having external outgoing connections." ;
            sh:message "s223: Disallow contained equipment from having external outgoing connections." ;
            sh:path s223:connectedTo ;
            sh:sparql [ a sh:SPARQLConstraint ;
                    rdfs:comment "Disallow contained equipment from having external outgoing connections." ;
                    sh:message "s223: {$this} should not have a connection to external equipment {?otherDev} because {?container} contains {$this}." ;
                    sh:prefixes ns6:model ;
                    sh:select """
SELECT $this ?container ?otherDev
WHERE {
$this s223:connectedTo ?otherDev .
$this ^s223:contains ?container .
?container a/rdfs:subClassOf* s223:Equipment .
FILTER NOT EXISTS {?container s223:contains ?otherDev .}
}
""" ] ],
        [ rdfs:comment "Warning about a subclass of `Equipment` of type A containing something that is in the same subclass branch." ;
            sh:message "s223: Warning about a subclass of `Equipment` of type A containing something that is in the same subclass branch." ;
            sh:path s223:contains ;
            sh:severity sh:Warning ;
            sh:sparql [ a sh:SPARQLConstraint ;
                    rdfs:comment "Warning about a subclass of `Equipment` of type A containing something that is in the same subclass branch." ;
                    sh:message "s223: {$this}, of type {?type1}, contains {?subEquip} of type {?type2}, that could result in double-counting items in the class hierarchy of {?type1}." ;
                    sh:prefixes ns6:model ;
                    sh:select """
SELECT $this ?subEquip ?type1 ?type2
WHERE {
  FILTER NOT EXISTS {$this a s223:Equipment} .
$this s223:contains+ ?subEquip .
  FILTER NOT EXISTS {?subEquip a s223:Equipment} .
$this a ?type1 .
?subEquip a ?type2 .
{
?type2 rdfs:subClassOf* ?type1 .
}
UNION
{
?type1 rdfs:subClassOf* ?type2 .
}
}
""" ] ] .

