| `FiberOpticCable-OM2` |
| `FiberOpticCable-OM3` |
| `FiberOpticCable-OM4` |
| `FiberOpticCable-OM5` |
| `FiberOpticCable-OS1` |
| `FiberOpticCable-OS2` |""" ;
    rdfs:subClassOf s223:Waveguide ;
    sh:property [ rdfs:comment "A `FiberOpticCable` shall be associated with exactly one `Signal-FiberEthernet` or `Wideband-CATV` using the relation `hasMedium`." ;
            sh:maxCount 1 ;
            sh:message "s223: A `FiberOpticCable` shall be associated with exactly one `Signal-FiberEthernet` or `Wideband-CATV` using the relation `hasMedium`." ;
