@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

s223:GaugePressureSensor a s223:Class,
        sh:NodeShape ;
    rdfs:label "Gauge pressure sensor" ;
    rdfs:comment """A `PressureSensor` that `observes` a `QuantifiableObservableProperty` that represents a measure of pressure relative to atmospheric pressure.
Such sensors are commonly used to monitor compressed gas cylinders, for example, where a gauge reading of zero signifies that the measured pressure
is equal to the atmospheric pressure, not a vacuum.""" ;
    rdfs:subClassOf s223:PressureSensor ;
    sh:property [ rdfs:comment "A `GaugePressureSensor` shall always observe a `QuantifiableObservableProperty` that has a `QuantityKind` of GaugePressure and a value of `true` for `qudt:isDeltaQuantity`." ;
            sh:class s223:QuantifiableObservableProperty ;
            sh:message "s223: A `GaugePressureSensor` shall always observe a `QuantifiableObservableProperty` that has a `QuantityKind` of GaugePressure and a value of `true` for `qudt:isDeltaQuantity`." ;
            sh:node [ sh:property [ sh:in ( qudtqk:GaugePressure ) ;
                            sh:path qudt:hasQuantityKind ],
                        [ sh:in ( true ) ;
                            sh:path qudt:isDeltaQuantity ] ] ;
            sh:path s223:observes ] .

