                                [ sh:class s223:OutletConnectionPoint ;
                                    sh:minCount 1 ;
                                    sh:path s223:pairedConnectionPoint ] ] ] ],
        [ rdfs:comment "A `HydronicHeatExchanger` shall have at least two outlets using the medium `Mix-Fluid`, each paired with an inlet." ;
