@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

s223:RadiantHeater a s223:Class,
        sh:NodeShape ;
    rdfs:label "Radiant heater" ;
    rdfs:comment """
A piece of `Equipment` with heating or cooling surface that delivers 50% or more of its heat transfer by radiation.
A `RadiantHeater` shall:

- Have the role `Role-Heating`.

- Have at least one outlet connection point using the medium `Light-Infrared`.

- Conform to exactly one of the following patterns:
  - **Pattern 1:**
    - Exactly one inlet connection point using the medium `Constituent-Electricity` or `Fluid-NaturalGas`.
  - **Pattern 2:**
    - Exactly one inlet connection point using the medium `Fluid-Water`.
    - Exactly one outlet connection point using the medium `Fluid-Water`.
""" ;
    rdfs:subClassOf s223:Equipment ;
    sh:property [ rdfs:comment "A `RadiantHeater` shall at least have the role `Role-Heating`." ;
            sh:message "s223: A `RadiantHeater` shall at least have the role `Role-Heating`." ;
            sh:path s223:hasRole ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:Role-Heating ] ],
        [ rdfs:comment "A `RadiantHeater` shall have at least one outlet using the medium `Light-Infrared`." ;
            sh:message "s223: A `RadiantHeater` shall have at least one outlet using the medium `Light-Infrared`." ;
            sh:path s223:hasConnectionPoint ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class s223:OutletConnectionPoint ;
                    sh:node [ sh:property [ sh:class s223:Light-Infrared ;
                                    sh:path s223:hasMedium ] ] ] ] ;
    sh:xone ( [ sh:property [ rdfs:comment "Pattern 1: A `RadiantHeater` shall have at least one inlet using the medium `Constituent-Electricity` or `Fluid-NaturalGas`." ;
                        sh:message "s223: Pattern 1: A `RadiantHeater` shall have at least one inlet using the medium `Constituent-Electricity` or `Fluid-NaturalGas`." ;
                        sh:path s223:hasConnectionPoint ;
                        sh:qualifiedMinCount 1 ;
                        sh:qualifiedValueShape [ sh:class s223:InletConnectionPoint ;
                                sh:node [ sh:property [ sh:or ( [ sh:class s223:Constituent-Electricity ] [ sh:class s223:Fluid-NaturalGas ] ) ;
                                                sh:path s223:hasMedium ] ] ] ] ] [ sh:property [ rdfs:comment "Pattern 2: A `RadiantHeater` shall have at least one inlet using the medium `Fluid-Water`." ;
                        sh:message "s223: Pattern 2: A `RadiantHeater` shall have at least one inlet using the medium `Fluid-Water`." ;
                        sh:path s223:hasConnectionPoint ;
                        sh:qualifiedMinCount 1 ;
                        sh:qualifiedValueShape [ sh:class s223:InletConnectionPoint ;
                                sh:node [ sh:property [ sh:class s223:Fluid-Water ;
                                                sh:path s223:hasMedium ] ] ] ],
                    [ rdfs:comment "Pattern 2: A `RadiantHeater` shall have at least one outlet using the medium `Fluid-Water`." ;
                        sh:message "s223: Pattern 2: A `RadiantHeater` shall have at least one outlet using the medium `Fluid-Water`." ;
                        sh:path s223:hasConnectionPoint ;
                        sh:qualifiedMinCount 1 ;
                        sh:qualifiedValueShape [ sh:class s223:OutletConnectionPoint ;
                                sh:node [ sh:property [ sh:class s223:Fluid-Water ;
                                                sh:path s223:hasMedium ] ] ] ] ] ) .

