    sh:class s223:Zone ;
    sh:message "s223: A `Zone` shall be associated with at least one `DomainSpace` using the relation `hasDomainSpace` or at least one `Zone` using the relation `hasZone`." ;
    sh:path s223:hasZone .

cbds.c14n284:
@prefix g36: <http://data.ashrae.org/standard223/1.0/extensions/g36#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
