pub:zone doc:subclauses ( s223:Zone s223:hasDomainSpace s223:hasZone ) ;
    doc:title "ZONE" ;
    rdfs:comment """
    A `Zone` is a logical grouping of one or more `DomainSpace`s and/or `Zone`s of a specific domain for some building service or control-related purpose. Multiple `Zone`s of the same domain may overlap. For example, a `Zone` that defines `DomainSpace`s that are subject to an occupancy-control strategy may overlap with a `Zone` that defines `DomainSpace`s that are subject to a supervisory scheduled-control strategy.""" .

c14n207.cbd:
@prefix ns6: <http://data.ashrae.org/standard223/1.0/validation/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

[] rdfs:comment "Every `Property` must have a comment." ;
    sh:path rdfs:comment ;
    sh:sparql [ a sh:SPARQLConstraint ;
            sh:message "s223: {$this} must have an rdfs:comment" ;
            sh:prefixes ns6:schema ;
            sh:select """
SELECT $this
WHERE {
BIND(REPLACE(STR($this), "^(.*)(/|#)([^#/]*)$", "$1") AS ?prop) .
FILTER (?prop = "http://data.ashrae.org/standard223") .
FILTER (NOT EXISTS {$this rdfs:comment ?something}) .
}
""" ] .

