[] a sh:SPARQLRule ;
    rdfs:comment "Infer the `hasAspect s223:Aspect-Setpoint` for properties referred to by `hasSetpoint`" ;
    sh:construct """
CONSTRUCT {?y s223:hasAspect  s223:Aspect-Setpoint}
